	try {
		const retirement = authenticatedRetirementPair(input);
		if (retirement === undefined) return failure("TRUST_CLOSURE_INVALID");
		const withoutRetirement = (
			closure: CreatorTransitionClosure,
			candidate?: DetachedClosureCandidate
